package com.saifulothman.bbma;

import android.app.*; import android.os.*; import android.graphics.*; import android.graphics.drawable.*; import android.view.*; import android.content.*; import java.util.*;

public class MainActivity extends Activity {
  BBMAView v;
  @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(Color.rgb(8,17,31)); v=new BBMAView(this); setContentView(v);}
}
class BBMAView extends View {
 Paint p=new Paint(1); int tab=0; float d; String[] tabs={"Dashboard","Chart","Signals","Positions","Settings"};
 int bg=Color.rgb(8,17,31), card=Color.rgb(17,29,47), white=Color.WHITE, muted=Color.rgb(156,171,190), green=Color.rgb(55,220,145), red=Color.rgb(255,92,106), blue=Color.rgb(75,150,255), yellow=Color.rgb(245,190,70);
 BBMAView(Context c){super(c); d=getResources().getDisplayMetrics().density; p.setTypeface(Typeface.create("sans",0)); setBackgroundColor(bg);}
 float S(float x){return x*d;} void txt(Canvas c,String s,float x,float y,float size,int col){p.setTextSize(S(size));p.setColor(col);p.setTypeface(Typeface.create("sans",Typeface.NORMAL));c.drawText(s,S(x),S(y),p);} void bold(Canvas c,String s,float x,float y,float size,int col){p.setTextSize(S(size));p.setColor(col);p.setTypeface(Typeface.create("sans",Typeface.BOLD));c.drawText(s,S(x),S(y),p);}
 void rect(Canvas c,float l,float t,float r,float b,int col,float rad){p.setColor(col);c.drawRoundRect(S(l),S(t),S(r),S(b),S(rad),S(rad),p);}
 @Override protected void onDraw(Canvas c){super.onDraw(c); c.drawColor(bg); float W=getWidth()/d; bold(c,"SAIFUL OTHMAN",18,30,20,white);txt(c,"BBMA TRADING SYSTEM",18,49,11,muted);rect(c,W-65,15,W-18,37,Color.rgb(22,70,54),12);bold(c,"LIVE",W-54,31,10,green);txt(c,tabs[tab],18,78,16,white); if(tab==0) dashboard(c,W); else if(tab==1) chart(c,W); else if(tab==2) signals(c,W); else if(tab==3) positions(c,W); else settings(c,W); nav(c,W); }
 void dashboard(Canvas c,float W){card(c,18,92,W-18,155);bold(c,"EURUSD  •  M15",30,116,16,white);txt(c,"TREND H4",30,139,10,muted);bold(c,"BUY",100,139,12,green);txt(c,"CONFIRM H1",170,139,10,muted);bold(c,"BUY",255,139,12,green);bold(c,"BUY SIGNAL  7/9",30,151,13,green);card(c,18,166,W-18,280);String[] a={"MOMENTUM","RE-ENTRY","EXTREME","CSAK"};String[] b={"BUY","BUY","WAIT","BUY"};for(int i=0;i<4;i++){float x=30+(i%2)*(W/2-20), y=192+(i/2)*42;txt(c,a[i],x,y,10,muted);bold(c,b[i],x,y+18,12,b[i].equals("WAIT")?yellow:green);}card(c,18,291,W-18,390);txt(c,"TRADE PLAN",30,315,10,muted);bold(c,"ENTRY",30,340,10,muted);bold(c,"1.17320",30,360,18,white);bold(c,"SL",170,340,10,muted);bold(c,"1.17120",170,360,18,red);bold(c,"TP",310,340,10,muted);bold(c,"1.17720",310,360,18,green);rect(c,30,370,(W-30)/2,384,green,7);rect(c,W/2,370,W-30,384,red,7); }
 void card(Canvas c,float l,float t,float r,float b){rect(c,l,t,r,b,card,16);}
 void chart(Canvas c,float W){card(c,18,92,W-18,395);bold(c,"EURUSD",30,117,17,white);txt(c,"M15",92,117,11,muted);float L=32,T=145,R=W-32,B=365; p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(S(2));p.setColor(blue);Path path=new Path();for(int i=0;i<80;i++){float x=L+(R-L)*i/79f;float y=250-(float)(45*Math.sin(i*.22)+18*Math.sin(i*.55)+i*.25);if(i==0)path.moveTo(S(x),S(y));else path.lineTo(S(x),S(y));}c.drawPath(path,p);p.setStyle(Paint.Style.FILL);line(c,L,205,R,205,green);line(c,L,290,R,290,red);txt(c,"TP 1.17720",R-80,201,9,green);txt(c,"SL 1.17120",R-80,286,9,red);bold(c,"1.17320",30,385,14,white);}
 void line(Canvas c,float x,float y,float x2,float y2,int col){p.setColor(col);p.setStrokeWidth(S(1));c.drawLine(S(x),S(y),S(x2),S(y2),p);}
 void signals(Canvas c,float W){String[][] rows={{"EURUSD","BUY","7/9"},{"GBPUSD","BUY","6/9"},{"XAUUSD","SELL","6/9"}};for(int i=0;i<3;i++){float y=95+i*88;card(c,18,y,W-18,y+72);bold(c,rows[i][0],30,y+28,16,white);bold(c,rows[i][1],W-115,y+28,13,rows[i][1].equals("SELL")?red:green);txt(c,"BBMA confirmation",30,y+51,10,muted);txt(c,rows[i][2],W-55,y+51,11,muted);}}
 void positions(Canvas c,float W){card(c,18,95,W-18,180);bold(c,"EURUSD BUY",30,123,16,white);txt(c,"0.10 lot",30,147,11,muted);bold(c,"+34.50",W-95,127,15,green);card(c,18,190,W-18,275);bold(c,"GBPUSD BUY",30,218,16,white);txt(c,"0.10 lot",30,242,11,muted);bold(c,"+21.80",W-95,222,15,green);bold(c,"TOTAL PROFIT",30,315,11,muted);bold(c,"+56.30",30,343,28,green);txt(c,"Balance  1,842.70",30,365,11,white);}
 void settings(Canvas c,float W){String[] s={"Account","Risk per trade","Alerts","BBMA Settings","Version"};String[] val={"Demo Account","2.0%","ON","M15 / H1 / H4","V1.0"};for(int i=0;i<s.length;i++){float y=100+i*62;card(c,18,y,W-18,y+50);txt(c,s[i],30,y+21,13,white);txt(c,val[i],W-125,y+21,11,muted);}}
 void nav(Canvas c,float W){float top=getHeight()/d-67;rect(c,0,top,W,top+67,Color.rgb(11,22,37),0);for(int i=0;i<5;i++){float x=W*(i+.5f)/5; if(i==tab)rect(c,x-24,top+9,x+24,top+12,blue,3);txt(c,new String[]{"⌂","⌁","!","$","⚙"}[i],x-7,top+34,18,i==tab?blue:muted);txt(c,new String[]{"Home","Chart","Signals","Positions","Settings"}[i],x-24,top+53,9,i==tab?white:muted);}}
 @Override public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()!=MotionEvent.ACTION_UP)return true;float x=e.getX()/d,y=e.getY()/d;float top=getHeight()/d-67;if(y>=top){int i=(int)(x/(getWidth()/d/5));if(i>=0&&i<5){tab=i;invalidate();}}return true;}
}
